  {
    if (row < 1 || row > rows - 2 || col < 1 || col > cols - 2)
    {
      return false;
    }
    if (!(cell[row][col] instanceof FillableCell))
    {
      return false;
    }
    FillableCell fc = (FillableCell) cell[row][col];
    if (fc.getPipe() != null)
    {
      return false;
    }
    fc.setPipe(pipe);
    return true;
  }

