  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Propagates water outward from the SOURCE using a BFS-style
   *          expansion that fills any pipe cell whose connection to a
   *          already-filled neighbour matches (i.e., one pipe's direction is
   *          the opposite of its neighbour's).
   * Algorithm:
   *   1. Reset the working frontier and pre-allocate a new filledTiles list.
   *   2. Push the source cell as the initial frontier (BFS seed).
   *   3. For each cell in the frontier, examine its four neighbours within
   *      the playable area.
   *   4. For each neighbour:
   *        a. If neighbour is unfilled and holds a pipe whose connections
   *           include a direction opposite to the direction from the current
   *           cell, and the current cell's connections include the matching
   *           direction, mark the neighbour as filled and add it to the next
   *           frontier.
   *   5. Repeat the expansion until no more cells are filled or the distance
   *      budget is exhausted.
   *   6. Update prevFilledTiles to the number of newly filled cells in this
   *      round and update prevFilledDistance.
   * Related Features: cell : Cell[][], filledTiles : List<Coordinate>,
   *                   prevFilledTiles : int, prevFilledDistance, sourceCell,
   *                   sinkCell.
   * Related Classes: Cell, FillableCell, Pipe, Direction, Coordinate, Pa19Helper
   *                   (for getOpposite and getOffset).
   * Input: distance : int — the number of BFS layers to expand from the source.
   *                      Typically the positive result of DelayBar.distance().
   * Output: void.
   * Pre-condition: fillBeginTile() has been called so the source is marked
   *                filled; the map has been constructed with a valid source cell.
   * Post-condition: All reachable pipes within `distance` BFS layers are marked
   *                as filled; prevFilledTiles and prevFilledDistance are updated
   *                for the subsequent loss check.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    EList<Coordinate> newFilled = new BasicEList<Coordinate>();
    EList<Coordinate> frontier = new BasicEList<Coordinate>();
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    
    Coordinate srcCoord = sourceCell.getCoord();
    frontier.add(srcCoord);
    
    int newFilledCount = 0;
    int dist = distance;
    while (!frontier.isEmpty() && dist > 0)
    {
      EList<Coordinate> nextFrontier = new BasicEList<Coordinate>();
      for (Coordinate cur : frontier)
      {
        for (Direction dir : Direction.VALUES)
        {
          Direction opposite = helper.getOpposite(dir);
          Coordinate offset = helper.getOffset(dir);
          Coordinate nbCoord = cur.add(offset);
          Cell nb = cell[nbCoord.getRow()][nbCoord.getCol()];
          if (nb instanceof FillableCell)
          {
            FillableCell nbFc = (FillableCell) nb;
            Pipe nbPipe = nbFc.getPipe();
            Cell curCell = cell[cur.getRow()][cur.getCol()];
            if (nbPipe != null && !nbPipe.isFilled()
                && nbPipe.getConnections().contains(opposite))
            {
              boolean curMatches = false;
              if (curCell instanceof FillableCell)
              {
                Pipe curPipe = ((FillableCell) curCell).getPipe();
                if (curPipe != null && curPipe.getConnections().contains(dir))
                {
                  curMatches = true;
                }
              }
              else if (curCell instanceof TerminationCell)
              {
                TerminationCell curTc = (TerminationCell) curCell;
                if (curTc.isFilled() && curTc.getPointingTo() == dir)
                {
                  curMatches = true;
                }
              }
              if (curMatches)
              {
                nbPipe.setFilled(true);
                newFilled.add(nbCoord);
                nextFrontier.add(nbCoord);
                newFilledCount++;
              }
            }
          }
        }
      }
      frontier = nextFrontier;
      dist--;
    }
    
    this.filledTiles = newFilled;
    this.prevFilledTiles = newFilledCount;
    this.prevFilledDistance = distance;
  }

